#top-settings-holder > .drawer > .drawer-content :is(input[type="text"],input[type="search"],input[type="number"],textarea,select,.text_pole) {
  background:rgba(255,255,255,.83)!important;
  color:#31546c!important;
  border:1px solid rgba(112,165,188,.78)!important;
  border-radius:3px!important;
  box-shadow:inset 0 1px 2px rgba(64,123,153,.06)!important;
}
#top-settings-holder > .drawer > .drawer-content :is(.menu_button,.menu_button_icon,button) {
  background:rgba(229,247,250,.92)!important;
  color:#31546c!important;
  border:1px solid rgba(105,160,184,.82)!important;
  border-radius:3px!important;
  box-shadow:2px 2px 0 rgba(104,163,186,.33)!important;
}
#top-settings-holder > .drawer > .drawer-content :is(.menu_button,.menu_button_icon,button):hover {
  background:rgba(206,239,244,.98)!important;
}
#top-settings-holder > .drawer > .drawer-content :is(.menu_button,.menu_button_icon,button):active {
  box-shadow:none!important;
}
/* The range input stays native and keyboard-operable; only its rail and thumb change. */
#top-settings-holder > .drawer > .drawer-content input[type="range"] {
  --dream-slider-thumb:var(--dream-menu-ice);
  -webkit-appearance:none!important;
  appearance:none!important;
  height:8px!important;
  margin-top:12px!important;
  border:1px solid rgba(102,157,179,.75)!important;
  border-radius:2px!important;
  background:linear-gradient(90deg,rgba(181,226,239,.93),rgba(234,248,251,.94))!important;
  box-shadow:inset 0 1px 2px rgba(55,103,129,.13)!important;
  filter:none!important;
  cursor:pointer!important;
}
#top-settings-holder > .drawer > .drawer-content input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance:none!important;
  appearance:none!important;
  width:30px!important;
  height:30px!important;
  border:0!important;
  border-radius:0!important;
  background:var(--dream-slider-thumb) center/contain no-repeat!important;
  box-shadow:none!important;
  image-rendering:pixelated;
  cursor:grab;
}
#top-settings-holder > .drawer > .drawer-content input[type="range"]::-moz-range-thumb {
  width:30px!important;
  height:30px!important;
  border:0!important;
  border-radius:0!important;
  background:var(--dream-slider-thumb) center/contain no-repeat!important;
  box-shadow:none!important;
  image-rendering:pixelated;
  cursor:grab;
}
#top-settings-holder > .drawer > .drawer-content input[type="range"]:active::-webkit-slider-thumb {cursor:grabbing;}
#top-settings-holder > .drawer > .drawer-content input[type="range"]:active::-moz-range-thumb {cursor:grabbing;}
#top-settings-holder > .drawer > .drawer-content input[type="range"]:focus-visible {
  outline:2px solid #d988a8!important;
  outline-offset:7px!important;
}
#chat_width_slider {--dream-slider-thumb:var(--dream-menu-ice)!important;}
#font_scale {--dream-slider-thumb:var(--dream-menu-flower)!important;}
#blur_strength {--dream-slider-thumb:var(--dream-menu-lemon)!important;}
#shadow_width {--dream-slider-thumb:var(--dream-small-star)!important;}
@media(max-width:700px) {
  #top-settings-holder > .drawer > .drawer-content :is(h2,h3) {font-size:16px!important;}
  #top-settings-holder > .drawer > .drawer-content input[type="range"]::-webkit-slider-thumb {width:27px!important;height:27px!important;}
  #top-settings-holder > .drawer > .drawer-content input[type="range"]::-moz-range-thumb {width:27px!important;height:27px!important;}
}

/* Shared controls: a light blue paper edge ties the navigation and composer to the cards. */
#top-bar, #top-settings-holder, body #top-settings-holder, body.no-blur #top-bar {
  background:linear-gradient(180deg,#fcfeff 0%,#eff9fc 100%)!important;
  box-shadow:0 2px 0 rgba(96,157,184,.6),0 5px 12px rgba(53,108,137,.09)!important;
}
#top-settings-holder > .drawer {background:transparent!important;}
body.no-blur #send_form, #send_form {
  background:linear-gradient(180deg,#fcfeff 0%,#eef8fb 100%)!important;
  border:1px solid rgba(97,156,182,.7)!important;
  border-image:none!important;
  border-radius:9px!important;
  box-shadow:0 4px 14px rgba(54,110,141,.13),inset 0 1px rgba(255,255,255,.9)!important;
}
#send_form #send_textarea {
  background:rgba(255,255,255,.64)!important;
  color:var(--dream-ink)!important;
  border-radius:6px!important;
}
#send_form :is(#send_but,#options_button,#extensionsMenuButton,.mes_stop) {color:#477b91!important;}
#rightSendForm > #mes_stop {
  width:var(--bottomFormBlockSize);height:var(--bottomFormBlockSize);
  flex:0 0 var(--bottomFormBlockSize);align-items:center;justify-content:center;
  align-self:center;margin:0;padding:0!important;box-sizing:border-box;
}
#rightSendForm > #mes_stop > .fa-circle-stop {display:none!important;}
#rightSendForm > #mes_stop::before {display:block;flex:none;vertical-align:initial;}

/* Toastr ships strong traffic-light fills. Keep its status meaning with a soft left mark. */
#toast-container > div {
  position:relative;
  width:min(360px,calc(100vw - 24px));
  padding:12px 16px 12px 47px!important;
  border:2px solid rgba(106,151,166,.42)!important;
  border-radius:4px!important;
  background-image:none!important;
  box-shadow:3px 3px 0 rgba(88,145,164,.22),0 7px 18px rgba(48,85,105,.12)!important;
  color:var(--dream-ink)!important;
  opacity:1!important;
  text-shadow:none!important;
}
#toast-container > div:hover {box-shadow:3px 3px 0 rgba(88,145,164,.3),0 8px 20px rgba(48,85,105,.17)!important;}
#toast-container > div.toast-success,
#toast-container > div.toast-error,
#toast-container > div.toast-warning,
#toast-container > div.toast-info {background-image:none!important;}
#toast-container > .toast-success {--toast-accent:#73a995;background-color:#e2f2e9!important;}
#toast-container > .toast-error {--toast-accent:#c28298;background-color:#f7e5eb!important;}
#toast-container > .toast-warning {--toast-accent:#c3a16d;background-color:#fff1dd!important;}
#toast-container > .toast-info {--toast-accent:#79a8c1;background-color:#e1f1f9!important;}
#toast-container > div::before {
  content:"✦";position:absolute;left:16px;top:50%;transform:translateY(-50%);
  color:var(--toast-accent);font:700 22px/1 sans-serif;pointer-events:none;
}
#toast-container > div::after {
  content:"";position:absolute;top:6px;right:7px;width:42px;height:3px;
  background:repeating-linear-gradient(90deg,var(--toast-accent,#7faabc) 0 5px,transparent 5px 9px);
  opacity:.48;pointer-events:none;
}
#toast-container > .toast-success::before {content:"✓";}
#toast-container > .toast-error::before {content:"!";}
#toast-container > .toast-warning::before {content:"!";}
#toast-container :is(.toast-title,.toast-message,.toast-close-button,.toast-message a,.toast-message label) {color:var(--dream-ink)!important;text-shadow:none!important;}
#toast-container .toast-progress {background:var(--toast-accent)!important;opacity:.55!important;}

/* Native highlighting is designed for a black code surface; these values fit our pale paper. */
#chat .mes_text pre, #chat .mes_reasoning pre {
  background:#f1f8fa!important;
  border:1px solid rgba(95,154,178,.68)!important;
  border-radius:6px!important;
  color:#304a60!important;
  text-shadow:none!important;
}
#chat .mes_text pre code, #chat .mes_reasoning pre code,
#chat .mes_text pre code.hljs, #chat .mes_reasoning pre code.hljs {
  background:transparent!important;color:#304a60!important;text-shadow:none!important;
}
#chat :is(.mes_text,.mes_reasoning) pre :is(.hljs-comment,.hljs-tag) {color:#667b87!important;}
#chat :is(.mes_text,.mes_reasoning) pre :is(.hljs-string,.hljs-addition,.hljs-code) {color:#496f63!important;}
#chat :is(.mes_text,.mes_reasoning) pre :is(.hljs-attr,.hljs-link,.hljs-literal,.hljs-number,.hljs-symbol,.hljs-title,.hljs-strong) {color:#735e91!important;}
#chat :is(.mes_text,.mes_reasoning) pre :is(.hljs-template-variable,.hljs-variable,.hljs-name,.hljs-deletion,.hljs-selector-tag) {color:#a65878!important;}
#chat :is(.mes_text,.mes_reasoning) pre :is(.hljs-keyword,.hljs-built_in,.hljs-type,.hljs-meta,.hljs-section,.hljs-attribute) {color:#326e87!important;}
#chat :is(.mes_text,.mes_reasoning) pre :is(.hljs-operator,.hljs-punctuation,.hljs-subst) {color:#405c71!important;}

