/* Startup postcard. The standalone copy in public/css/user.css also covers the first frame. */
#preloader {
  background:linear-gradient(150deg,#d9f1fb,#f6fbff 58%,#fbe8f0)!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}
#preloader::before {
  content:"正在初始化…";
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  box-sizing:border-box;width:min(84vw,520px);height:260px;
  padding:170px 24px 20px;text-align:center;
  font:500 16px/1.5 "Microsoft YaHei",sans-serif;
  letter-spacing:.06em;color:#3d6880;
  background:
    repeating-linear-gradient(0deg,rgba(116,174,208,.06) 0 2px,transparent 2px 11px),
    repeating-linear-gradient(90deg,rgba(116,174,208,.06) 0 2px,transparent 2px 11px),
    rgba(255,255,255,.86);
  border:3px dashed rgba(255,255,255,.96);border-radius:15px;
  box-shadow:0 7px 24px rgba(61,125,157,.17),inset 0 0 0 1px rgba(104,167,197,.25);
}
#preloader::after {
  content:"";position:absolute;left:calc(50% - 19px);top:calc(50% - 53px);transform:scale(2);
  width:38px;height:38px;
  background-image:var(--dream-topbar-icons);background-size:177.175px 80.275px;
  background-position:-91px -2px;background-repeat:no-repeat;image-rendering:pixelated;
  mix-blend-mode:multiply;
}
body:has(#loader.splash-screen) #preloader {display:none!important;}
html:has(#loader.splash-screen),body:has(#loader.splash-screen) {overflow:hidden!important;}
body:has(#loader.splash-screen) :is(#top-bar,#top-settings-holder,#sheld,#form_sheld) {visibility:hidden!important;}

dialog.popup:has(#loader.splash-screen) {
  box-sizing:border-box;width:min(84vw,540px)!important;height:min(50dvh,320px)!important;
  min-width:0!important;max-width:84vw!important;max-height:50dvh!important;
  padding:0!important;margin:auto!important;
  background:transparent!important;border:0!important;border-image:none!important;
  border-radius:0!important;box-shadow:none!important;overflow:visible!important;
}
dialog.popup:has(#loader.splash-screen)::backdrop {background:rgba(71,128,159,.26)!important;}
dialog.popup:has(#loader.splash-screen) :is(.popup-body,.popup-content) {
  width:100%!important;height:100%!important;padding:0!important;margin:0!important;
  background:transparent!important;border:0!important;box-shadow:none!important;
}
#loader.splash-screen {
  box-sizing:border-box;position:relative;width:100%!important;height:100%!important;
  display:flex!important;flex-direction:column;align-items:center;justify-content:center;
  gap:28px!important;padding:28px 20px!important;
  background:
    repeating-linear-gradient(0deg,rgba(118,177,213,.055) 0 2px,transparent 2px 11px),
    repeating-linear-gradient(90deg,rgba(118,177,213,.055) 0 2px,transparent 2px 11px),
    linear-gradient(150deg,rgba(249,254,255,.97),rgba(218,241,251,.96) 65%,rgba(255,232,241,.94));
  border:3px dashed rgba(255,255,255,.98);border-radius:15px;
  box-shadow:0 8px 25px rgba(50,109,142,.18),inset 0 0 0 1px rgba(95,162,198,.3);
  color:#2c5b79!important;
}
#loader.splash-screen .splash-logo {display:none!important;}
#loader.splash-screen::after {
  content:"✦  SUMMER POST  ✦";
  color:#788ea4;font:12px/1.4 monospace;letter-spacing:.18em;text-align:center;
}
#loader.splash-screen #load-spinner {
  position:static!important;top:auto!important;left:auto!important;
  display:block!important;width:38px!important;height:38px!important;
  opacity:1!important;font-size:0!important;animation:dream-loader-bob 1.6s ease-in-out infinite!important;
}
#loader.splash-screen #load-spinner::before {
  content:""!important;display:block;width:38px;height:38px;
  background-image:var(--dream-topbar-icons)!important;
  background-size:177.175px 80.275px!important;
  background-position:-91px -2px!important;background-repeat:no-repeat!important;
  image-rendering:pixelated;mix-blend-mode:multiply;
}
#loader.splash-screen .splash-message {
  margin:0!important;color:#3d6880!important;
  font:500 16px/1.5 "Microsoft YaHei",sans-serif!important;
  letter-spacing:.08em!important;opacity:1!important;
}
@keyframes dream-loader-bob {
  0%,100% {transform:scale(2) translateY(0);}
  50% {transform:scale(2) translateY(-4px);}
}
@media(prefers-reduced-motion:reduce) {#loader.splash-screen #load-spinner {animation:none!important;}}

@media(max-width:700px){#bg1{background-image:url("data:image/webp;base64,")!important;}}
